package com.openggf.game.soniccd;
import org.junit.jupiter.api.*;import org.junit.jupiter.api.io.TempDir;import org.junit.jupiter.api.parallel.Isolated;import java.nio.file.Path;
import static org.junit.jupiter.api.Assertions.*;import static com.openggf.game.soniccd.objects.CdObjectState.ByteField.*;import static com.openggf.game.soniccd.objects.CdObjectState.WordField.*;
/** ALL Java UNRUN. Genuine public Boot/World/Frame with clearly labelled constructed
 * public pool controls; no snapshots/diagnostic rows or private operation authority. */
@Isolated class TestSonicCdR31aSpringWorld {
 @TempDir Path directory;final TestSonicCdR31aSelectedProfileLoading f=new TestSonicCdR31aSelectedProfileLoading();
 @BeforeEach void setup(){f.directory=directory;f.setup();}@AfterEach void cleanup(){f.cleanup();}
 @Test void constructedPublicPoolSpringInitialisesOnceThroughTheActualWorldWithoutWarpReset()throws Exception{try(var b=f.start(1,0x80)){ready(b);var h=b.module.r31WorldHost();var p=h.placement().pool();clear(p);var m=b.module.requirePlayerFrame().state().motion();p.write(p.state(32).moveByte(ID,0x0A).moveWord(X,(m.centreX16_16()>>>16)+64).moveWord(Y,100));var g=b.module.requirePlayerFrame().environment().movement().gates();TestSonicCdR31aSelectedProfileLoading.step(b,8);assertEquals(2,p.state(32).routine());assertEquals(0x520,p.state(32).word(TILE));assertEquals(g.timeWarpDirection(),b.module.requirePlayerFrame().environment().movement().gates().timeWarpDirection());}}
 @Test void fullCourseRestoreReplaysTheSameSourceOwnedSpringAndSoundLedger()throws Exception{try(var b=f.start(1,0x80)){ready(b);var h=b.module.r31WorldHost();var frame=b.module.requirePlayerFrame();var p=h.placement().pool();clear(p);var m=frame.state().motion();p.write(p.state(32).moveByte(ID,0x0A).moveWord(X,(m.centreX16_16()>>>16)+64).moveWord(Y,100));var r=b.mode.getRewindRegistry();var full=r.capture();var course=r.captureCourse();TestSonicCdR31aSelectedProfileLoading.step(b,8);var after=TestSonicCdR31aSelectedProfileLoading.values(b);for(boolean c:new boolean[]{false,true}){if(c)r.restoreCourse(course);else r.restore(full);TestSonicCdR31aSelectedProfileLoading.step(b,8);assertEquals(after,TestSonicCdR31aSelectedProfileLoading.values(b));assertSame(frame,b.module.requirePlayerFrame());assertSame(h,b.module.r31WorldHost());}}}
 private static void ready(TestSonicCdR31aSelectedProfileLoading.Booted b){TestSonicCdR31aSelectedProfileLoading.ready(b);TestSonicCdR31aSelectedProfileLoading.step(b,8);}private static void clear(com.openggf.game.soniccd.objects.CdObjectPool p){for(int w=32;w<128;w++)p.deleteObject(w);}
}
